std::string context;
void check(bool ok,const std::string& why){if(!ok)throw std::runtime_error(context+": "+why);}
std::vector<Pixel> words(const JsonArray& a){std::vector<Pixel> result;for(auto v:a)result.push_back(Pixel(v.GetNumber()));return result;}
void pixels(const std::vector<Pixel>& actual,const JsonArray& expected){check(actual==words(expected),"raw IDs");}
void encoded(const Document& d){bool duplicates=false;std::unordered_set<int> ids;for(const auto& e:d.palette().entries)duplicates|=!ids.insert(e.id).second;
 for(int k=0;k<3;++k){try{auto out=k==0?project::encodeEditableProject(d):k==1?project::encodeRecoveryProject(d):project::encodeHistoryProject(d);check(!duplicates,"encoder accepted duplicates");auto m=project::readProjectManifest(out.bytes);project::Archive zip(out.bytes);check(m.colorMode=="indexed","encoded mode");for(const auto& c:m.cels)if(c.surface){const auto* runtime=d.timeline().resolveSurface(c.id).surface;const auto& s=*c.surface;check(runtime&&s.format==project::RasterFormat::Indexed&&project::decodeRaster(zip.read(s.dataFile,project::Limits{}.expandedBytes),s.dataEncoding,s.format,s.width,s.height,project::Limits{}.expandedBytes)==runtime->pixels,"encoded raw IDs");}check(m.palette.size()==d.palette().entries.size(),"encoded palette");bool gated=false;try{project::prepareEditableImport(m);}catch(const project::Error& e){gated=e.kind==project::ErrorKind::Unsupported;}check(gated,"production indexed gate");}catch(const project::Error& e){check(duplicates&&e.kind==project::ErrorKind::Corrupt,"encoder error");}}
}
